mapper.select:
select a.activity_num, a.organization_num, a.activity_id, a.activity_name, a.activity_detail, a.activity_begintime, a.activity_endtime, a.activity_location, a.activity_needpeople, a.activity_notice, a.activity_publishtime, a.activity_signddl, a.activity_state, a.activity_checkin_code, a.activity_latitude, a.activity_longitude, a.activity_radius, (select group_concat(s.skill_name order by s.skill_name separator ',') from activity_skill s where s.activity_num = a.activity_num) as activity_skill_names, case when a.activity_latitude is null or a.activity_longitude is null or #{latitude,jdbcType=DECIMAL} is null or #{longitude,jdbcType=DECIMAL} is null then null else round(st_distance_sphere(point(a.activity_longitude, a.activity_latitude), point(#{longitude,jdbcType=DECIMAL}, #{latitude,jdbcType=DECIMAL}))) end as distance_meters, (select count(*) from participate p join activity pa on pa.activity_num = p.activity_num where p.volunteer_num = #{volunteerNum,jdbcType=INTEGER} and p.participate_isdeleted = 0 and p.participate_applystate in ('0', '1', '3') and pa.organization_num = a.organization_num) as organization_history_count from activity a where a.activity_isdeleted = 0
and a.activity_num = #{activityNum,jdbcType=INTEGER}
and a.activity_state = '1' and (a.activity_signddl is null or a.activity_signddl > now()) and (a.activity_endtime is null or a.activity_endtime > now()) and not exists (select 1 from participate p2 where p2.activity_num = a.activity_num and p2.volunteer_num = #{volunteerNum,jdbcType=INTEGER} and p2.participate_isdeleted = 0)
and (a.activity_name like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or a.activity_id like concat('%', #{keyword,jdbcType=VARCHAR}, '%') or a.activity_location like concat('%', #{keyword,jdbcType=VARCHAR}, '%'))
order by a.activity_begintime asc
limit #{limitCount,jdbcType=INTEGER}
